const COSMO={H0:67.4,Om:0.315,Or:9.2e-5,Ol:1-0.315-9.2e-5,T0:2.7255};
function hubble(a){return COSMO.H0*Math.sqrt(COSMO.Or/a**4+COSMO.Om/a**3+COSMO.Ol)}
const expansionTable=[];
{const n=8000,min=-12,dh=-min*Math.LN10/n,Hsec=COSMO.H0/3.0856775814913673e19;let t=0,last=0;for(let i=0;i<=n;i++){const a=10**(min+i*(-min/n));const f=1/(Hsec*Math.sqrt(COSMO.Or/a**4+COSMO.Om/a**3+COSMO.Ol));if(i)t+=(last+f)*dh/2;else t=a*a/(2*Hsec*Math.sqrt(COSMO.Or));expansionTable.push([t,a]);last=f;}}
function scaleAtTime(t){if(t>=expansionTable.at(-1)[0])return 1;let l=0,r=expansionTable.length-1;while(r-l>1){const m=(l+r)>>1;if(expansionTable[m][0]<t)l=m;else r=m;}const p=expansionTable[l],q=expansionTable[r];return Math.exp(Math.log(p[1])+(Math.log(t/p[0])/Math.log(q[0]/p[0]))*Math.log(q[1]/p[1]));}
function timeAtChapter(p){const i=Math.min(10,Math.floor(p));return Math.exp(Math.log(ERAS[i].t)+(p-i)*Math.log(ERAS[i+1].t/ERAS[i].t));}
let numberLocale='';
const numberFormats=new Map();
function formatNumber(value,max=2,min=0,options={}) {
 const key=JSON.stringify([numberLocale,max,min,options]);
 if(!numberFormats.has(key))numberFormats.set(key,new Intl.NumberFormat(numberLocale||undefined,{maximumFractionDigits:max,minimumFractionDigits:min,...options}));
 return numberFormats.get(key).format(value);
}
function formatAge(t){if(t<.001){const e=Math.floor(Math.log10(t)+1e-8);return [formatNumber(t/10**e,1)+' × 10<sup>'+e+'</sup>','seconds'];}if(t<60)return [formatNumber(Number(t.toPrecision(3)),3),'seconds'];if(t<3600)return [formatNumber(t/60,1,1),'minutes'];if(t<YEAR)return [formatNumber(t/86400,1,1),'days'];const y=t/YEAR;return y>=1e9?[formatNumber(y/1e9,2,2),'billion years']:y>=1e6?[formatNumber(y/1e6,1,1),'million years']:[formatNumber(Math.round(y),0),'years'];}
// Conventional 18-group display with detached complete lanthanoid/actinoid rows.
function periodicPosition(z){
 if(z>=57&&z<=71)return {row:9,column:z-53};
 if(z>=89&&z<=103)return {row:10,column:z-85};
 if(z===1)return {row:1,column:1};if(z===2)return {row:1,column:18};
 const starts=[3,11,19,37,55,87];
 const period=starts.findLastIndex(start=>z>=start),start=starts[period];
 let column=z-start+1;
 if(period<2&&column>2)column+=10;
 if(period>=4&&column>2)column-=14;
 return {row:period+2,column};
}
