function elementOrigin(z){if(z<=2)return ['Primordial + stellar','Made as nuclei in the early universe; neutral atoms form later. Stars subsequently change the inventory.'];if(z===3)return ['Big Bang, cosmic rays & stars','Primordial lithium is a trace component. Cosmic-ray reactions and stellar sources, including novae, add lithium later.'];if(z<=5)return ['Mostly cosmic-ray fragmentation','Energetic particles fragment larger nuclei. Boron also has other contributions; primordial beryllium-7 is unstable and decays to lithium.'];if(z<=30)return ['Stellar burning & explosions','Multiple burning and explosive pathways contribute, with fractions depending on element and isotope. This broad category is not a claim of one exclusive source.'];if(z===43||z===61)return ['Radioactive products','No stable isotopes. Stellar nuclear reactions can produce short-lived nuclei; laboratory synthesis also produces this element.'];if(z<=83)return ['Neutron capture & other pathways','Slow and rapid neutron capture contribute across this region of the table. Isotope-specific origins vary; some isotopes need additional processes.'];if(z<=92)return ['Radioactive nuclei & decay chains','Rapid neutron capture makes long-lived actinides and unstable progenitors. Natural abundances also depend on radioactive decay; not all these elements survive from formation.'];return ['Artificial production; possible cosmic transients','Known terrestrial samples are principally synthesized. Some transuranic nuclei also arise transiently in nature; no claim is made that every superheavy element is abundant in the cosmos.'];}
